&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Other duties as assigned or needed.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Skills You’ll Need:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At least 5 years of experience working in a Talent/Learning Development, &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Campus Recruitment or HR Business Partner role, including experience &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;working with campus/early careers talent.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
